"""K1663 figures: (1) GMV OOS vol + turnover bars, (2) rolling annualised vol path."""
from __future__ import annotations

import json
from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

HERE = Path(__file__).resolve().parent
res = json.load(open(HERE / "K1663_rcov_har_gmv_results.json"))
# _series.npz is generated by this experiment's own main script (trusted, self-produced);
# allow_pickle is only needed for the string date array.
ser = np.load(HERE / "_series.npz", allow_pickle=True)

LAB = {
    "har_chol": "HAR-Cholesky",
    "rolling": "Rolling 22d",
    "ewma": "EWMA 0.94",
    "ledoit_wolf": "Ledoit-Wolf",
    "equal_weight": "1/N equal-wt",
}
COL = {
    "har_chol": "#d1495b",
    "rolling": "#edae49",
    "ewma": "#66a182",
    "ledoit_wolf": "#2e4057",
    "equal_weight": "#8d96a3",
}
ORDER = ["har_chol", "rolling", "ewma", "ledoit_wolf", "equal_weight"]
ls = res["constraints"]["long_short"]["metrics"]
oos = res["oos_period"]

# ---------------------------------------------------------------------------
# Figure 1: annualised GMV vol (bars) + turnover (bars) side by side
# ---------------------------------------------------------------------------
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(13, 5.2))

vols = [ls[m]["ann_vol"] * 100 for m in ORDER]
cols = [COL[m] for m in ORDER]
labs = [LAB[m] for m in ORDER]
b1 = ax1.bar(labs, vols, color=cols, edgecolor="black", linewidth=0.6)
ax1.set_ylabel("Annualised OOS portfolio volatility (%)")
ax1.set_title("(a) GMV realised volatility — lower is better")
ax1.axhline(vols[ORDER.index("ledoit_wolf")], ls="--", lw=0.8, color="grey")
for r, v in zip(b1, vols):
    ax1.text(r.get_x() + r.get_width() / 2, v + 0.06, f"{v:.2f}", ha="center", fontsize=9)
ax1.set_ylim(0, max(vols) * 1.15)
ax1.tick_params(axis="x", rotation=18)

turns = [ls[m]["avg_daily_turnover"] for m in ORDER]
b2 = ax2.bar(labs, turns, color=cols, edgecolor="black", linewidth=0.6)
ax2.set_ylabel("Avg daily turnover  Σ|Δw|")
ax2.set_title("(b) Turnover — lower is cheaper to trade")
for r, v in zip(b2, turns):
    ax2.text(r.get_x() + r.get_width() / 2, v + 0.004, f"{v:.3f}", ha="center", fontsize=9)
ax2.set_ylim(0, max(turns) * 1.18)
ax2.tick_params(axis="x", rotation=18)

fig.suptitle(
    f"K1663 · RCov-HAR → GMV portfolio (long-short) · OOS {oos['start']}..{oos['end']} "
    f"({oos['oos_days']} days) · SPY/QQQ/GLD/TLT/IWM",
    fontsize=11,
)
fig.tight_layout(rect=(0, 0, 1, 0.96))
fig.savefig(HERE / "K1663_gmv_vol_turnover.png", dpi=140)
plt.close(fig)

# ---------------------------------------------------------------------------
# Figure 2: rolling 63-day annualised vol path per method
# ---------------------------------------------------------------------------
dates = pd.to_datetime([str(d) for d in ser["dates"]])
fig2, ax = plt.subplots(figsize=(13, 5.2))
for m in ["har_chol", "ewma", "ledoit_wolf"]:
    p = pd.Series(ser[f"pret_{m}"], index=dates)
    roll = p.rolling(63).std() * np.sqrt(252) * 100
    ax.plot(dates, roll, label=LAB[m], color=COL[m], lw=1.1)
ax.set_ylabel("Rolling 63-day annualised vol (%)")
ax.set_title(
    "K1663 · GMV rolling realised volatility (long-short) — EWMA lowest through "
    "GFC/COVID/2022; HAR-RCov does not beat it"
)
ax.legend(loc="upper right", fontsize=9)
# shade stress windows
for lo, hi, lab in [("2008-09-01", "2009-06-30", "GFC"),
                    ("2020-02-20", "2020-05-31", "COVID"),
                    ("2022-01-01", "2022-10-31", "2022 bear")]:
    ax.axvspan(pd.Timestamp(lo), pd.Timestamp(hi), color="grey", alpha=0.12)
    ax.text(pd.Timestamp(lo), ax.get_ylim()[1] * 0.92, lab, fontsize=8, color="dimgrey")
fig2.tight_layout()
fig2.savefig(HERE / "K1663_gmv_rolling_vol.png", dpi=140)
plt.close(fig2)

print("[plots] saved K1663_gmv_vol_turnover.png, K1663_gmv_rolling_vol.png")
